import numpy as np


def build_vocab(text):
    chars = sorted(set(text))
    char_to_idx = {c: i for i, c in enumerate(chars)}
    idx_to_char = {i: c for i, c in enumerate(chars)}
    return chars, char_to_idx, idx_to_char


def make_training_pairs(text, seq_len, char_to_idx):
    ids = [char_to_idx[c] for c in text]
    return [(ids[i:i + seq_len], ids[i + 1:i + seq_len + 1]) for i in range(len(ids) - seq_len)]


def softmax_with_temperature(logits, temperature=1.0):
    z = logits / temperature
    e = np.exp(z - np.max(z))
    return e / e.sum()


text = "def add(a, b):\n    return a + b\n"
vocab = build_vocab(text)
if vocab is not None:
    chars, char_to_idx, idx_to_char = vocab
    print("vocabulary size:", len(chars))
    pairs = make_training_pairs(text, 5, char_to_idx)
    if pairs is not None:
        x_ids, y_ids = pairs[0]
        print("training pairs:", len(pairs))
        print("first input :", repr("".join(idx_to_char[i] for i in x_ids)))
        print("first target:", repr("".join(idx_to_char[i] for i in y_ids)))

logits = np.array([2.0, 1.0, 0.1])
for t in (0.5, 1.0, 2.0):
    probs = softmax_with_temperature(logits, t)
    print("temperature", t, "->", None if probs is None else np.round(probs, 3))
